local GlassAnnealingCradleMaker = {}
local PRODUCTS = {
    iron_glassannealingcradle = { name = "Železni zibka za ohlajanje stekla", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zibka za ohlajanje stekla za steklarje." },
    bronze_glassannealingcradle = { name = "Bronast zibka za ohlajanje stekla", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zibka za ohlajanje stekla za steklarje." },
    silver_glassannealingcradle = { name = "Srebrn zibka za ohlajanje stekla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zibka za ohlajanje stekla za steklarje." },
    gilded_glassannealingcradle = { name = "Pozlačen zibka za ohlajanje stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zibka za ohlajanje stekla za steklarje." },
    jewel_set_glassannealingcradle = { name = "Draguljast zibka za ohlajanje stekla", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zibka za ohlajanje stekla za steklarje." },
    royal_sovereign_glassannealingcradle = { name = "Kraljevski suveren zibka za ohlajanje stekla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zibka za ohlajanje stekla z biseri za krono." },
}
local BUILDINGS = {
    glassannealingcradle_workshop = { name = "Glassannealingcradle delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassannealingcradle_house = { name = "Glassannealingcradle hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassannealingcradle_atelier = { name = "Mojstrski glassannealingcradle atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassannealingcradle_palace = { name = "Suverena glassannealingcradle palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassAnnealingCradleMaker.ironStock=14; GlassAnnealingCradleMaker.bronzeStock=12; GlassAnnealingCradleMaker.woodStock=14; GlassAnnealingCradleMaker.leatherStock=8; GlassAnnealingCradleMaker.silverStock=8; GlassAnnealingCradleMaker.goldStock=6; GlassAnnealingCradleMaker.jewelStock=4; GlassAnnealingCradleMaker.pearlStock=4
GlassAnnealingCradleMaker.productStock = {}; GlassAnnealingCradleMaker.buildings = {}; GlassAnnealingCradleMaker.maker = nil; GlassAnnealingCradleMaker.activeMaking = {}; GlassAnnealingCradleMaker.totalProducts = 0; GlassAnnealingCradleMaker.dayTimer = 0
function GlassAnnealingCradleMaker.init() GlassAnnealingCradleMaker.ironStock=14; GlassAnnealingCradleMaker.bronzeStock=12; GlassAnnealingCradleMaker.woodStock=14; GlassAnnealingCradleMaker.leatherStock=8; GlassAnnealingCradleMaker.silverStock=8; GlassAnnealingCradleMaker.goldStock=6; GlassAnnealingCradleMaker.jewelStock=4; GlassAnnealingCradleMaker.pearlStock=4; GlassAnnealingCradleMaker.productStock={}; GlassAnnealingCradleMaker.buildings={}; GlassAnnealingCradleMaker.maker=nil; GlassAnnealingCradleMaker.activeMaking={}; GlassAnnealingCradleMaker.totalProducts=0; GlassAnnealingCradleMaker.dayTimer=0; print("[GlassAnnealingCradleMaker] Royal Glass Annealing Cradle Maker System initialized (6 products, 4 buildings)") end
function GlassAnnealingCradleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassAnnealingCradleMaker.maker={name=n or ("Zibkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zibkar najet: %s (spretnost: %d)",GlassAnnealingCradleMaker.maker.name,s),"success") end; return true end
function GlassAnnealingCradleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassAnnealingCradleMaker.build(id) local ok,e=GlassAnnealingCradleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassAnnealingCradleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassAnnealingCradleMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassAnnealingCradleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassAnnealingCradleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassAnnealingCradleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassAnnealingCradleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassAnnealingCradleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassAnnealingCradleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassAnnealingCradleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassAnnealingCradleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassAnnealingCradleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassAnnealingCradleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassAnnealingCradleMaker.buildings==0 then return false,"Potrebna zibna delavnica" end; if not GlassAnnealingCradleMaker.maker then return false,"Potreben zibkar" end; return true end
function GlassAnnealingCradleMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassAnnealingCradleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassAnnealingCradleMaker.ironStock=GlassAnnealingCradleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassAnnealingCradleMaker.bronzeStock=GlassAnnealingCradleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassAnnealingCradleMaker.woodStock=GlassAnnealingCradleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassAnnealingCradleMaker.leatherStock=GlassAnnealingCradleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassAnnealingCradleMaker.silverStock=GlassAnnealingCradleMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassAnnealingCradleMaker.goldStock=GlassAnnealingCradleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassAnnealingCradleMaker.jewelStock=GlassAnnealingCradleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassAnnealingCradleMaker.pearlStock=GlassAnnealingCradleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassAnnealingCradleMaker.maker then t=math.max(1,t-math.floor(GlassAnnealingCradleMaker.maker.skill/13)) end; table.insert(GlassAnnealingCradleMaker.activeMaking,{id="glassannealingcradle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassAnnealingCradleMaker.completeMaking(m) local q=1.0+(GlassAnnealingCradleMaker.getQualityBonus()/100); if GlassAnnealingCradleMaker.maker then q=q+(GlassAnnealingCradleMaker.maker.skill/140) end; q=math.min(2.5,q); GlassAnnealingCradleMaker.productStock[m.productType]=(GlassAnnealingCradleMaker.productStock[m.productType] or 0)+m.quantity; GlassAnnealingCradleMaker.totalProducts=GlassAnnealingCradleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassAnnealingCradleMaker.maker then GlassAnnealingCradleMaker.maker.itemsMade=GlassAnnealingCradleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassAnnealingCradleMaker.maker.skill=math.min(100,GlassAnnealingCradleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zibka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassannealingcradle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassAnnealingCradleMaker.update(dt) if not _G.state then return end; GlassAnnealingCradleMaker.dayTimer=GlassAnnealingCradleMaker.dayTimer+dt; if GlassAnnealingCradleMaker.dayTimer>=30 then GlassAnnealingCradleMaker.dayTimer=0; for i=#GlassAnnealingCradleMaker.activeMaking,1,-1 do local m=GlassAnnealingCradleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassAnnealingCradleMaker.completeMaking(m); table.remove(GlassAnnealingCradleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassAnnealingCradleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassAnnealingCradleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassAnnealingCradleMaker.getStats() return {ironStock=GlassAnnealingCradleMaker.ironStock,bronzeStock=GlassAnnealingCradleMaker.bronzeStock,woodStock=GlassAnnealingCradleMaker.woodStock,leatherStock=GlassAnnealingCradleMaker.leatherStock,silverStock=GlassAnnealingCradleMaker.silverStock,goldStock=GlassAnnealingCradleMaker.goldStock,jewelStock=GlassAnnealingCradleMaker.jewelStock,pearlStock=GlassAnnealingCradleMaker.pearlStock,productStock=GlassAnnealingCradleMaker.productStock,numBuildings=#GlassAnnealingCradleMaker.buildings,hasMaker=GlassAnnealingCradleMaker.maker~=nil,makerName=GlassAnnealingCradleMaker.maker and GlassAnnealingCradleMaker.maker.name or "—",makerSkill=GlassAnnealingCradleMaker.maker and GlassAnnealingCradleMaker.maker.skill or 0,activeMaking=#GlassAnnealingCradleMaker.activeMaking,totalProducts=GlassAnnealingCradleMaker.totalProducts} end
return GlassAnnealingCradleMaker
